  "Glass Parts Sculpture": "Skulptur Glass Parts",
  "Tiffany stained glass in a light box": "Tiffanyglas i en ljuslåda",
  "Curved glass object — 2019": "Objekt i böjt glas — 2019",
  "Studio": "Ateljé",
  "Butoh performance": "Butoh-föreställning",
  "Kaleidoscope": "Kalejdoskop",
  "18 pieces": "18 verk",
